def _cpfs(cifrar: bool) -> None:
    """Cifra (ou decifra, no downgrade) os CPFs já gravados."""
    from app.cripto import cifrar as cf, decifrar as df

    con = op.get_bind()
    for tabela, coluna in (("entidade", "documento"), ("contraparte", "documento"), ("transacao", "contraparte_documento")):
        linhas = con.execute(sa.text(f"SELECT id, {coluna} FROM {tabela} WHERE {coluna} IS NOT NULL")).all()
        for id_, v in linhas:
            novo = cf(v) if cifrar else df(v)
            if novo != v:
                con.execute(sa.text(f"UPDATE {tabela} SET {coluna} = :v WHERE id = :id"), {"v": novo, "id": id_})


